patches.diff:
From 34e57c58ea6b9f39b5ad05f70ce88fef09b5c98c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:46:35 +0100
Subject: [PATCH] applets/weather: Add an option to detect the current location

The widget only showed the weather for a fixed place, so it was wrong
whenever the device moved. It can now follow the location reported by
the system's location service, like Night Light, with Open-Meteo data.

BUG: 475219
---
 CMakeLists.txt                                |  7 ++++
 applets/weather/main.xml                      |  3 ++
 applets/weather/qml/FullRepresentation.qml    | 21 +++++++++-
 .../qml/config/ConfigWeatherStation.qml       | 39 +++++++++++++++----
 applets/weather/qml/main.qml                  | 33 ++++++++++++++--
 5 files changed, 91 insertions(+), 12 deletions(-)

diff --git a/CMakeLists.txt b/CMakeLists.txt
index d483a5d85..9d73b4ca4 100644
--- a/CMakeLists.txt
+++ b/CMakeLists.txt
@@ -118,6 +118,13 @@ set_package_properties(Qt6Graphs PROPERTIES
     TYPE RUNTIME
 )

+find_package(Qt6Positioning CONFIG)
+set_package_properties(Qt6Positioning PROPERTIES
+    DESCRIPTION "QtPositioning QML plugin for location services"
+    PURPOSE "Required for detecting the current location in the weather applet"
+    TYPE RUNTIME
+)
+
 find_package(Corrosion REQUIRED)

 add_definitions(
diff --git a/applets/weather/main.xml b/applets/weather/main.xml
index 0bf4efa0f..652f617d9 100644
--- a/applets/weather/main.xml
+++ b/applets/weather/main.xml
@@ -25,6 +25,9 @@ SPDX-License-Identifier: GPL-2.0-or-later
     <entry name="source" type="string">
       <default></default>
     </entry>
+    <entry name="useCurrentLocation" type="bool">
+      <default>false</default>
+    </entry>
   </group>

   <group name="Appearance">
diff --git a/applets/weather/qml/FullRepresentation.qml b/applets/weather/qml/FullRepresentation.qml
index f959bfe85..88ab006e0 100644
--- a/applets/weather/qml/FullRepresentation.qml
+++ b/applets/weather/qml/FullRepresentation.qml
@@ -19,6 +19,7 @@ PlasmaExtras.Representation {
     id: root

     property int status: 0
+    property bool currentLocationUnavailable: false

     required property bool showHourlyTemperatureGraph
     required property bool showDayTemperatureGraph
@@ -90,12 +91,30 @@ PlasmaExtras.Representation {
         anchors.centerIn: parent
         anchors.margins: Kirigami.Units.largeSpacing * 4
         width: Math.min(parent.width, Kirigami.Units.gridUnit * 20)
-        visible: root.status === ForecastControl.Timeout
+        visible: root.status === ForecastControl.Timeout && !root.currentLocationUnavailable
         iconName: "network-disconnect"
         text: !!root.station?.place ? i18nc("@info:status PlaceholderMessage text", "Unable to retrieve weather information for %1", root.station.place) : i18nc("@info:status PlaceholderMessage text", "Unable to retrieve weather information")
         explanation: i18nc("@info:usagetip", "The network request timed out, possibly due to a server outage at the weather station provider. Check again later.")
     }

+    PlasmaExtras.PlaceholderMessage {
+        anchors.centerIn: parent
+        anchors.margins: Kirigami.Units.largeSpacing * 4
+        width: Math.min(parent.width, Kirigami.Units.gridUnit * 20)
+        visible: root.currentLocationUnavailable
+        iconName: "mark-location"
+        text: i18nc("@info:status PlaceholderMessage text", "Unable to determine your current location")
+        explanation: i18nc("@info:usagetip", "Location services may be unavailable or turned off. You can choose a location manually instead.")
+        helpfulAction: QQC2.Action {
+            icon.name: "configure"
+            text: i18nc("@action:button PlaceholderMessage helpfulAction", "Set location…")
+
+            onTriggered: {
+                Plasmoid.internalAction("configure").trigger();
+            }
+        }
+    }
+
     PlasmaExtras.PlaceholderMessage {
         visible: !stack.visible && root.status === ForecastControl.Normal
         anchors.centerIn: parent
diff --git a/applets/weather/qml/config/ConfigWeatherStation.qml b/applets/weather/qml/config/ConfigWeatherStation.qml
index d6e5d367e..62ee336cd 100644
--- a/applets/weather/qml/config/ConfigWeatherStation.qml
+++ b/applets/weather/qml/config/ConfigWeatherStation.qml
@@ -29,8 +29,10 @@ KCM.ScrollViewKCM {
     property string cfg_placeDisplayName

     property alias cfg_updateInterval: updateIntervalSpin.value
+    property bool cfg_useCurrentLocation

     readonly property bool hasSource: cfg_provider !== "" && cfg_placeInfo !== ""
+    readonly property bool showsProvider: hasSource || cfg_useCurrentLocation
     readonly property bool canSearch: !!searchStringEdit.text && locationListModel.hasProviders

     // The model property `isValidatingInput` doesn't account for the timer delay
@@ -75,9 +77,12 @@ KCM.ScrollViewKCM {

                 Layout.fillWidth: true
                 elide: Text.ElideRight
-                opacity: weatherStationConfigPage.hasSource ? 1 : 0.75
+                opacity: weatherStationConfigPage.hasSource || weatherStationConfigPage.cfg_useCurrentLocation ? 1 : 0.75

                 text: {
+                    if (weatherStationConfigPage.cfg_useCurrentLocation) {
+                        return i18nc("@title name of the place the weather is shown for", "Current Location");
+                    }
                     if (weatherStationConfigPage.hasSource) {
                         if (weatherStationConfigPage.cfg_placeDisplayName !== "") {
                             return weatherStationConfigPage.cfg_placeDisplayName;
@@ -90,14 +95,17 @@ KCM.ScrollViewKCM {
             }

             QQC2.Label {
-                Kirigami.FormData.label: weatherStationConfigPage.hasSource ? i18nc("@label", "Provider:") : ""
+                Kirigami.FormData.label: weatherStationConfigPage.showsProvider ? i18nc("@label", "Provider:") : ""

                 Layout.fillWidth: true
                 elide: Text.ElideRight
                 // Keep it visible to avoid height changes which can confuse AppletConfigurationPage
-                opacity: weatherStationConfigPage.hasSource ? 1 : 0
+                opacity: weatherStationConfigPage.showsProvider ? 1 : 0

                 text: {
+                    if (weatherStationConfigPage.cfg_useCurrentLocation) {
+                        return locationListModel.getProviderDisplayName("openmeteo");
+                    }
                     if (weatherStationConfigPage.hasSource) {
                         return locationListModel.getProviderDisplayName(weatherStationConfigPage.cfg_provider);
                     }
@@ -106,6 +114,18 @@ KCM.ScrollViewKCM {
                 textFormat: Text.PlainText
             }

+            QQC2.CheckBox {
+                text: i18nc("@option:check", "Detect my location automatically")
+                checked: weatherStationConfigPage.cfg_useCurrentLocation
+
+                onToggled: {
+                    weatherStationConfigPage.cfg_useCurrentLocation = checked;
+                    if (checked) {
+                        searchStringEdit.clear();
+                    }
+                }
+            }
+
             Item {
                 // This dummy item adds some spacing and makes the form layout less jumpy
                 Kirigami.FormData.isSection: true
@@ -115,7 +135,7 @@ KCM.ScrollViewKCM {

         Kirigami.InlineMessage {
             Layout.fillWidth: true
-            visible: ['wettercom', 'dwd'].includes(weatherStationConfigPage.cfg_provider)
+            visible: !weatherStationConfigPage.cfg_useCurrentLocation && ['wettercom', 'dwd'].includes(weatherStationConfigPage.cfg_provider)
             text: i18nc("@label:info. %1 is the name of a weather service",
                         "“%1” may not offer the current temperature or other weather conditions for this location.",
                         locationListModel.getProviderDisplayName(weatherStationConfigPage.cfg_provider))
@@ -127,7 +147,7 @@ KCM.ScrollViewKCM {
             Layout.fillWidth: true

             focus: true
-            enabled: locationListModel.hasProviders
+            enabled: locationListModel.hasProviders && !weatherStationConfigPage.cfg_useCurrentLocation
             placeholderText: weatherStationConfigPage.hasSource ? i18nc("@info:placeholder", "Enter new location") : i18nc("@info:placeholder", "Enter location")

             Timer {
@@ -176,7 +196,7 @@ KCM.ScrollViewKCM {
         focus: true
         activeFocusOnTab: true
         keyNavigationEnabled: true
-        enabled: locationListModel.hasProviders
+        enabled: locationListModel.hasProviders && !weatherStationConfigPage.cfg_useCurrentLocation

         onCurrentIndexChanged: {
             if (locationListView.currentIndex === -1) {
@@ -238,7 +258,9 @@ KCM.ScrollViewKCM {
             width: parent.width - (Kirigami.Units.largeSpacing * 4)
             visible: locationListView.count === 0 && !weatherStationConfigPage.isSearching
             text: {
-                if (weatherStationConfigPage.canSearch) {    // There is a search text
+                if (weatherStationConfigPage.cfg_useCurrentLocation) {
+                    return i18nc("@info", "The weather will be shown for your current location");
+                } else if (weatherStationConfigPage.canSearch) {    // There is a search text
                     return i18nc("@info", "No weather stations found for '%1'", searchStringEdit.text);
                 } else if (weatherStationConfigPage.hasSource) {
                     return i18nc("@info", "Search for a weather station to change your location");
@@ -246,7 +268,8 @@ KCM.ScrollViewKCM {
                     return i18nc("@info", "Search for a weather station to set your location");
                 }
             }
-            explanation: weatherStationConfigPage.canSearch ? i18nc("@info:usagetip", "If you've used this weather station in the past, it's possible that a server outage at the weather station provider has made it temporarily unavailable. Try again later.") : ""
+            explanation: weatherStationConfigPage.cfg_useCurrentLocation ? i18nc("@info:usagetip", "Your location is provided by the system's location service, and the forecast comes from Open-Meteo.")
+                : weatherStationConfigPage.canSearch ? i18nc("@info:usagetip", "If you've used this weather station in the past, it's possible that a server outage at the weather station provider has made it temporarily unavailable. Try again later.") : ""

         }

diff --git a/applets/weather/qml/main.qml b/applets/weather/qml/main.qml
index 10debeec6..c112db3ae 100644
--- a/applets/weather/qml/main.qml
+++ b/applets/weather/qml/main.qml
@@ -7,6 +7,7 @@
 pragma ComponentBehavior: Bound

 import QtQuick
+import QtPositioning

 import org.kde.plasma.plasmoid
 import org.kde.kirigami as Kirigami
@@ -42,6 +43,8 @@ PlasmoidItem {
             forecastControl.setUpdateInterval(root.updateInterval);
             forecastControl.setForecastLocation(root.weatherProvider, root.weatherPlaceInfo);
             //If the old source property present try to fetch forecast for it
+        } else if (root.useCurrentLocation) {
+            forecastControl.setForecastLocation("", "");
         } else if (Plasmoid.configuration.source.length > 0) {
             const sourceDetails = Plasmoid.configuration.source.split('|');
             forecastControl.setUpdateInterval(root.updateInterval);
@@ -54,15 +57,38 @@ PlasmoidItem {

     readonly property bool inPanel: [PlasmaCore.Types.TopEdge, PlasmaCore.Types.RightEdge, PlasmaCore.Types.BottomEdge, PlasmaCore.Types.LeftEdge,].includes(Plasmoid.location)

-    readonly property string weatherProvider: Plasmoid.configuration.provider
-    readonly property string weatherPlaceInfo: Plasmoid.configuration.placeInfo
+    PositionSource {
+        id: positionSource
+        active: root.useCurrentLocation
+    }
+
+    readonly property bool useCurrentLocation: Plasmoid.configuration.useCurrentLocation
+    readonly property bool currentLocationUnavailable: useCurrentLocation && currentLocationPlaceInfo.length === 0
+        && (!positionSource.valid || positionSource.sourceError !== PositionSource.NoError)
+    readonly property string currentLocationPlaceInfo: {
+        const position = positionSource.position;
+        if (!position.latitudeValid || !position.longitudeValid) {
+            return "";
+        }
+        return "%1||%2||%3".arg(i18nc("@title name of the place the weather is shown for", "Current Location"))
+            .arg(position.coordinate.latitude.toFixed(2))
+            .arg(position.coordinate.longitude.toFixed(2));
+    }
+
+    readonly property string weatherProvider: useCurrentLocation ? "openmeteo" : Plasmoid.configuration.provider
+    readonly property string weatherPlaceInfo: useCurrentLocation ? currentLocationPlaceInfo : Plasmoid.configuration.placeInfo
     readonly property int updateInterval: Plasmoid.configuration.updateInterval
     readonly property int displayTemperatureUnit: Plasmoid.configuration.temperatureUnit || TemperatureUnitListModel.defaultUnit
     readonly property int displaySpeedUnit: Plasmoid.configuration.speedUnit || WindSpeedUnitListModel.defaultUnit
     readonly property int displayPressureUnit: Plasmoid.configuration.pressureUnit || PressureUnitListModel.defaultUnit
     readonly property int displayVisibilityUnit: Plasmoid.configuration.visibilityUnit || VisibilityUnitListModel.defaultUnit

-    property alias status: forecastControl.status
+    readonly property int status: {
+        if (useCurrentLocation && currentLocationPlaceInfo.length === 0) {
+            return currentLocationUnavailable ? ForecastControl.Timeout : ForecastControl.Connecting;
+        }
+        return forecastControl.status;
+    }

     readonly property int invalidUnit: -1 //TODO: make KUnitConversion::InvalidUnit usable here

@@ -182,6 +208,7 @@ PlasmoidItem {

     fullRepresentation: FullRepresentation {
         status: root.status
+        currentLocationUnavailable: root.currentLocationUnavailable

         showHourlyTemperatureGraph: Plasmoid.configuration.showHourlyTemperatureGraph
         showDayTemperatureGraph: Plasmoid.configuration.showDayTemperatureGraph
-- 
2.53.0
